  'lista.lead': { pt: "Listas de compras por mercado, com histórico e gráficos de gastos. Sem cadastro.", en: "Shopping lists by store, with history and spending charts. No sign-up.", es: "Listas de compras por mercado, con historial y gráficos de gastos. Sin registro." },
