  'lista.spec-ads': { pt: "Sim: banner e intersticial. Você aceita ou recusa na primeira abertura e pode rever nas configurações.", en: "Yes: banner and interstitial. You accept or decline the first time you open the app and can review it in settings.", es: "Sí: banner e intersticial. Aceptas o rechazas la primera vez que abres la app y puedes revisarlo en la configuración." },
