  // ── WORD EVOLUTION ─────────────────────────────────────────
  'apps.word-desc': {
    pt: 'Word Evolution reinventa o caça-palavras clássico: cada tabuleiro é gerado proceduralmente no momento em que você joga, garantindo partidas sempre novas e desafios que nunca se repetem. Escolha entre 10 categorias de palavras e 3 níveis de dificuldade para ajustar o ritmo ao seu gosto. Ficou sem saber uma palavra? Use uma dica. Complete partidas, ganhe moedas e acompanhe sua evolução com estatísticas detalhadas de desempenho. Disponível em português, inglês, espanhol, francês e italiano, com temas claro e escuro para jogar a qualquer hora do dia.',
    en: 'Word Evolution reinvents the classic word search: every board is procedurally generated the moment you play, guaranteeing matches that are always new and challenges that never repeat. Choose from 10 word categories and 3 difficulty levels to match the pace to your taste. Stuck on a word? Use a hint. Complete matches, earn coins, and track your progress with detailed performance statistics. Available in Portuguese, English, Spanish, French, and Italian, with light and dark themes to play any time of day.',
    es: 'Word Evolution reinventa el clásico sopa de letras: cada tablero se genera proceduralmente en el momento en que juegas, garantizando partidas siempre nuevas y desafíos que nunca se repiten. Elige entre 10 categorías de palabras y 3 niveles de dificultad para ajustar el ritmo a tu gusto. ¿Te quedaste sin saber una palabra? Usa una pista. Completa partidas, gana monedas y sigue tu evolución con estadísticas detalladas de rendimiento. Disponible en portugués, inglés, español, francés e italiano, con temas claro y oscuro para jugar a cualquier hora del día.',
  },
  'word.lead': { pt: "Caça-palavras com tabuleiros novos a cada partida, 10 categorias e dicas.", en: "Word search with a new board every match, 10 categories and hints.", es: "Sopa de letras con tableros nuevos en cada partida, 10 categorías y pistas." },
  'word.trust-langs': { pt: "5 idiomas", en: "5 languages", es: "5 idiomas" },
