  'word.benefit1-d': { pt: "Cada tabuleiro é gerado na hora, a partir da categoria e da dificuldade que você escolher.", en: "Every board is generated on the spot, from the category and difficulty you choose.", es: "Cada tablero se genera en el momento, a partir de la categoría y la dificultad que elijas." },
  'word.benefit2-t': { pt: "Evolua jogando", en: "Level up as you play", es: "Evoluciona jugando" },
